  commandsEnabled?: boolean;
  defaultCwd?: string;
  toolNames: string[];
  createdAt: string;
  updatedAt: string;
}

export interface ChannelAccountView extends ChannelAccountConfig {
  configured: boolean;
  credentialFingerprint?: string;
}

export interface ChannelStatus {
  channel: ChannelId;
  accountId: string;
  state: ChannelRuntimeState;
  connected: boolean;
  lastStartAt?: number;
  lastConnectedAt?: number;
  lastEventAt?: number;
  lastInboundAt?: number;
  lastOutboundAt?: number;
  lastError?: string;
  retryCount?: number;
}

export interface ChannelPairingRequest {
  id: string;
  code: string;
  channel: ChannelId;
  accountId: string;
  peerId: string;
  displayName?: string;
  createdAt: string;
  expiresAt: string;
}

export interface ChannelBinding {
  id: string;
  channel: ChannelId;
  accountId: string;
  peerKind: "dm" | "group";
  peerId: string;
  threadId?: string;
  sessionId?: string;
  cwd: string;
  toolNames: string[];
  createdAt: string;
  lastUsedAt: string;
}

export interface ChannelBindingChange {
  action: "upsert" | "delete";
  bindingId: string;
  binding?: ChannelBinding;
}

export interface ChannelActivity {
  id: string;
  channel: ChannelId;
  accountId: string;
  direction: "inbound" | "outbound" | "system";
  outcome: "accepted" | "ignored" | "sent" | "failed";
  peerId?: string;
  at: string;
  detail?: string;
}

export interface ChannelsSnapshot {
  accounts: ChannelAccountView[];
  statuses: ChannelStatus[];
  pairings: ChannelPairingRequest[];
  bindings: ChannelBinding[];
  activities: ChannelActivity[];
}

export type ChannelLoginPhase =
  | "qr"
  | "waiting"
  | "scanned"
  | "verification_required"
  | "confirmed"
  | "already_connected"
  | "expired"
  | "error"
  | "cancelled";

export interface ChannelLoginEvent {
  channel: ChannelId;
  sessionKey: string;
  phase: ChannelLoginPhase;
  message: string;
  qrDataUrl?: string;
  qrContent?: string;
  accountId?: string;
  /** Earliest useful time for the Renderer to request another snapshot of this login session. */
  pollAfterMs?: number;
  /** Absolute Unix timestamp in milliseconds after which the QR/session is no longer usable. */
  expiresAt?: number;
