  ok: boolean;
  message: string;
  accountId: string;
  providerAccountId?: string;
  providerUsername?: string;
  displayName?: string;
}

export interface ChannelTestSendResult {
  ok: true;
  messageId: string;
}

export interface InboundAttachment {
  kind: "image" | "voice" | "file" | "video";
